const body = $json.body;
if (!body.instrument || !body.prompt) {
  throw new Error('Missing required parameters: instrument and prompt');
}
const validInstruments = ['bass', 'drums', 'guitar', 'piano', 'synth', 'vocal', 'other'];
if (!validInstruments.includes(body.instrument.toLowerCase())) {
  throw new Error('Invalid instrument: ' + body.instrument);
}

const executionId = $execution.id;
return {
  instrument: body.instrument.toLowerCase(),
  prompt: body.prompt,
  duration: Math.min(Math.max(parseInt(body.duration) || 30, 5), 300),
  temperature: Math.min(Math.max(parseFloat(body.temperature) || 1.0, 0.1), 2.0),
  topK: parseInt(body.topK) || 250,
  quality_threshold: parseInt(body.quality_threshold) || 70,
  outputFile: `/data/stems/${executionId}_${body.instrument.toLowerCase()}.wav`,
  executionId: executionId,
  timestamp: new Date().toISOString()
};

let result = {};
if ($json.stderr && $json.stderr.toLowerCase().includes('error')) {
  result = { success: false, error: $json.stderr, executionId: $('Validate & Prepare Vars').item.json.executionId };
  $response.statusCode = 500;
} else {
  try {
    const generationOutput = JSON.parse($json.stdout);
    result = { ...generationOutput, success: generationOutput.success !== undefined ? generationOutput.success : true, executionId: $('Validate & Prepare Vars').item.json.executionId };
    if (!result.success) $response.statusCode = 500; // If script itself indicates failure
  } catch (e) {
    result = { success: false, error: 'Failed to parse generation script output.', details: $json.stdout, executionId: $('Validate & Prepare Vars').item.json.executionId };
    $response.statusCode = 500;
  }
}
return result;

const body = $json.body;
if (!body.stems || !Array.isArray(body.stems) || body.stems.length === 0) {
  throw new Error('`stems` parameter is required and must be a non-empty array of file paths.');
}
for (const stem of body.stems) {
  if (typeof stem !== 'string' || !stem.startsWith('/data/')) { // Basic validation
            throw new Error('Invalid stem path: ' + stem + '. Stems should be absolute paths starting with /data/');
  }
}
const executionId = $execution.id;
return {
  stemsJson: JSON.stringify(body.stems),
  referenceTrack: body.referenceTrack || '',
  targetLUFS: body.targetLUFS || -14,
  outputFile: `/data/mixed/master_${executionId}.wav`,
  executionId: executionId
};

let result = {};
if ($json.stderr && $json.stderr.toLowerCase().includes('error')) {
  result = { success: false, error: $json.stderr, executionId: $('Validate & Prepare Mix').item.json.executionId };
  $response.statusCode = 500;
} else {
  try {
    const scriptOutput = JSON.parse($json.stdout);
    result = { ...scriptOutput, success: scriptOutput.success !== undefined ? scriptOutput.success : true, executionId: $('Validate & Prepare Mix').item.json.executionId };
    if (!result.success) $response.statusCode = 500;
  } catch (e) {
    result = { success: false, error: 'Failed to parse mix/master script output.', details: $json.stdout, executionId: $('Validate & Prepare Mix').item.json.executionId };
    $response.statusCode = 500;
  }
}
return result;

const body = $json.body;
const executionId = $execution.id;
const style = body.style || 'electronic';
const bpm = Math.min(Math.max(parseInt(body.bpm) || 120, 60), 200);
const key = body.key || 'C major';
const duration = Math.min(Math.max(parseInt(body.duration) || 60, 30), 300);
const complexity = Math.min(Math.max(parseInt(body.complexity) || 5, 1), 10);
const title = body.title || `AI ${style} Track ${executionId.substring(0,8)}`;

const styleTemplates = {
  'electronic': { instruments: ['bass', 'drums', 'synth', 'pad', 'fx'], stemDurationFactor: 0.6 },
  'rock': { instruments: ['bass', 'drums', 'guitar', 'lead_guitar'], stemDurationFactor: 0.7 },
  'jazz': { instruments: ['bass', 'drums', 'piano', 'sax'], stemDurationFactor: 0.5 },
  'ambient': { instruments: ['pad', 'texture', 'drone'], stemDurationFactor: 0.9 }
};
const template = styleTemplates[style.toLowerCase()] || styleTemplates['electronic'];
const instrumentsToGenerate = body.instruments || template.instruments;
const stemDuration = Math.max(15, Math.floor(duration * template.stemDurationFactor));

const generationTasks = instrumentsToGenerate.map(instrument => ({
  instrument: instrument,
  prompt: `${style} ${instrument}, ${bpm} BPM, ${key}, ${complexity}/10 complexity. ${title}`,
  duration: stemDuration,
  temperature: 1.0 + (complexity / 20 - 0.25), // Slightly vary temp with complexity
  topK: 250 - (complexity * 5),
  quality_threshold: 65 + complexity * 2 // Higher quality for more complex
}));

return {
  tasks: generationTasks,
  compositionParams: { style, bpm, key, duration, complexity, title, executionId, instruments: instrumentsToGenerate }
};

const generatedItems = $input.all();
const compositionParams = $('Prepare Composition Tasks').item.json.compositionParams;
const generatedStems = [];
let allStemsSucceeded = true;

for (const item of generatedItems) {
  // Check for success in the body of the HTTP Request node's result
  const responseBody = item.json.body; // HTTPRequest node puts response in 'body'
  if (responseBody && (responseBody.success || (responseBody.mcp_response && responseBody.mcp_response.success) ) ){
    const stemData = responseBody.mcp_response || responseBody;
    if(stemData.file) generatedStems.push(stemData.file);
    else { allStemsSucceeded = false; console.error('Stem generated but no file path:', stemData);}
  } else {
    allStemsSucceeded = false;
    console.error('A stem generation failed:', responseBody?.error || 'Unknown error in stem generation response');
  }
}

if (generatedStems.length === 0) {
  throw new Error('No stems were successfully generated for the composition.');
}

return {
  stems: generatedStems,
  title: compositionParams.title,
  executionId: compositionParams.executionId,
  allStemsSucceeded: allStemsSucceeded, 
  compositionMetadata: compositionParams
};

const mixNodeResult = $input.item.json.body; // HTTPRequest node puts response in 'body'
const collectionResult = $('Collect Stems for Mixing').item.json;

const mixData = mixNodeResult?.mcp_response || mixNodeResult;

if (!mixData || !mixData.success) {
  return { success: false, error: mixData?.error || 'Mixing process failed.', executionId: collectionResult.executionId };
}

return {
  success: true,
  executionId: collectionResult.executionId,
  composition: {
    title: collectionResult.title,
    file: mixData.file,
    report_file: mixData.report_file,
    quality_score: mixData.quality_score,
    duration: collectionResult.compositionMetadata.duration,
    bpm: collectionResult.compositionMetadata.bpm,
    key: collectionResult.compositionMetadata.key,
    style: collectionResult.compositionMetadata.style,
    stems_generated_paths: collectionResult.stems,
    all_stems_succeeded: collectionResult.allStemsSucceeded
  }
};
